// Local audio only. No external player, iframe or network music service.
const $=id=>document.getElementById(id);let sound,element,gain,blobURL,storedFile;
const dbReady=new Promise(resolve=>{try{const req=indexedDB.open('twelfth-night-music',1);req.onupgradeneeded=()=>req.result.createObjectStore('audio');req.onerror=()=>resolve(null);req.onsuccess=()=>{const db=req.result,r=db.transaction('audio').objectStore('audio').get('song');r.onsuccess=()=>{storedFile=r.result;resolve(db);};r.onerror=()=>resolve(db);};}catch{resolve(null);}});
function external(on){if(sound){sound.externalMusic=on;sound.setMusicVolume(sound.musicVolume);}}
function volume(){if(gain)gain.gain.value=sound?.musicVolume??.5;}
async function play(file=storedFile){if(!file)return false;if(!sound){$('music-feedback').textContent='已保存音频，进入城市后即可播放。';return false;}sound.start();if(!element||element._file!==file){element?.pause();if(blobURL)URL.revokeObjectURL(blobURL);blobURL=URL.createObjectURL(file);element=new Audio(blobURL);element._file=file;element.loop=true;gain=sound.ctx.createGain();sound.ctx.createMediaElementSource(element).connect(gain).connect(sound.master);}external(true);volume();await sound.ctx.resume();await element.play();return true;}
for(const id of ['music-open','intro-music'])$(id)?.addEventListener('click',()=>{$('music-panel').hidden=false;});$('music-close').onclick=()=>{$('music-panel').hidden=true;};
$('song-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;storedFile=f;try{const db=await dbReady;if(db)db.transaction('audio','readwrite').objectStore('audio').put(f,'song');$('music-feedback').textContent='已导入：'+f.name;await play(f);}catch{$('music-feedback').textContent='进入城市后点击播放；可选择 MP3 或 M4A。';}};
$('local-play').onclick=async()=>{if(element&&!element.paused){element.pause();external(false);return;}await dbReady;if(!storedFile){$('music-feedback').textContent='请先选择音频文件。';return;}try{await play();}catch{$('music-feedback').textContent='音频未能播放，请换用 MP3 或 M4A。';}};
addEventListener('city:volume',volume);window.citySong={attach(s){sound=s;},async start(){await dbReady;if(storedFile)play().catch(()=>{});},pause(){element?.pause();},resume(){if(element&&sound?.externalMusic)element.play().catch(()=>{});},restart(){if(element)element.currentTime=0;}};
